#!/usr/bin/env node
/**
 * Schema Freshness Check
 *
 * Verifies that generated files are up-to-date with schema/v1.json.
 * Run with: node schema/check-freshness.js
 *           yarn schema:check
 *
 * Exit codes:
 *   0 - Generated files are fresh
 *   1 - Generated files are stale (need regeneration)
 *
 * Usage in CI:
 *   yarn schema:check || (echo "Run 'yarn schema:codegen' and commit" && exit 1)
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import { execSync } from 'child_process';
import { createHash } from 'crypto';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const GENERATED_DIR = join(__dirname, 'generated');
const GENERATED_FILES = [
  'sqlite-full.sql',
  'sqlite-sync.sql',
  'types.ts',
  'types.rs',
  'validate.js',
];

/**
 * Get hash of file contents, ignoring the "Generated:" timestamp line
 */
function getContentHash(content) {
  // Remove the generated timestamp line since it changes every run
  const normalized = content.replace(/^.*Generated:.*$/m, '');
  return createHash('md5').update(normalized).digest('hex');
}

function main() {
  console.log('[freshness] Checking if generated files are up-to-date...\n');

  // Check if generated directory exists
  if (!existsSync(GENERATED_DIR)) {
    console.error('[freshness] ERROR: Generated directory does not exist');
    console.error('[freshness] Run "yarn schema:codegen" to generate files');
    process.exit(1);
  }

  // Read current generated files
  const currentHashes = {};
  for (const file of GENERATED_FILES) {
    const path = join(GENERATED_DIR, file);
    if (!existsSync(path)) {
      console.error(`[freshness] ERROR: Missing generated file: ${file}`);
      console.error('[freshness] Run "yarn schema:codegen" to generate files');
      process.exit(1);
    }
    currentHashes[file] = getContentHash(readFileSync(path, 'utf-8'));
  }

  // Re-run codegen to temporary location and compare
  console.log('[freshness] Re-running codegen to compare...');

  // Import and run codegen logic inline to avoid temp files
  const schemaPath = join(__dirname, 'v1.json');
  const schema = JSON.parse(readFileSync(schemaPath, 'utf-8'));

  // Simplified regeneration for comparison (matches codegen.js logic)
  const typeMap = {
    sqlite: { text: 'TEXT', integer: 'INTEGER', real: 'REAL', boolean: 'INTEGER' },
  };

  function generateSqlite(syncOnly) {
    const lines = ['-- Generated by schema/codegen.js'];
    lines.push(`-- Schema version: ${schema.version}`);
    lines.push('-- Generated: TIMESTAMP'); // Placeholder
    lines.push('-- DO NOT EDIT - regenerate with: yarn schema:codegen');
    lines.push('');

    for (const [tableName, table] of Object.entries(schema.tables)) {
      lines.push(`-- ${table.description || tableName}`);
      lines.push(`CREATE TABLE IF NOT EXISTS ${tableName} (`);

      const columnDefs = [];
      for (const [colName, col] of Object.entries(table.columns)) {
        if (syncOnly && col.sync === false) continue;
        let def = `  ${colName} ${typeMap.sqlite[col.type]}`;
        if (col.primary_key) def += ' PRIMARY KEY';
        if (col.not_null) def += ' NOT NULL';
        if (col.unique) def += ' UNIQUE';
        if (col.check) def += ` CHECK(${col.check})`;
        if (col.default !== undefined) def += ` DEFAULT ${col.default}`;
        columnDefs.push(def);
      }

      lines.push(columnDefs.join(',\n'));
      lines.push(');');
      lines.push('');

      for (const idx of (table.indexes || [])) {
        if (syncOnly && idx.sync === false) continue;
        const unique = idx.unique ? 'UNIQUE ' : '';
        const cols = idx.columns.join(', ');
        const order = idx.order ? ` ${idx.order}` : '';
        lines.push(`CREATE ${unique}INDEX IF NOT EXISTS ${idx.name} ON ${tableName}(${cols}${order});`);
      }
      lines.push('');
    }

    return lines.join('\n');
  }

  // Generate fresh content and compare hashes
  const freshContent = {
    'sqlite-full.sql': generateSqlite(false),
    'sqlite-sync.sql': generateSqlite(true),
  };

  let stale = false;

  // Only check SQL files for now (TypeScript/Rust have more complex generation)
  for (const file of ['sqlite-full.sql', 'sqlite-sync.sql']) {
    const freshHash = getContentHash(freshContent[file]);
    if (currentHashes[file] !== freshHash) {
      console.error(`[freshness] STALE: ${file}`);
      stale = true;
    } else {
      console.log(`[freshness] OK: ${file}`);
    }
  }

  // For other files, just check they exist (full comparison would duplicate codegen)
  for (const file of ['types.ts', 'types.rs', 'validate.js']) {
    console.log(`[freshness] OK: ${file} (exists)`);
  }

  console.log('');

  if (stale) {
    console.error('[freshness] Generated files are STALE');
    console.error('[freshness] Run "yarn schema:codegen" and commit the changes');
    process.exit(1);
  }

  console.log('[freshness] All generated files are up-to-date');
  process.exit(0);
}

main();
